import {Checkbox, Dialog, Form, Input, Select} from "tdesign-react";
import {use, useEffect, useState} from "react";

const {FormItem} = Form;

export default function UpdateWebsiteDialog({visible, website}) {
    const [_visible, setVisible] = useState(visible);
    const [categories, setCategories] = useState([]);

    useEffect(() => {
        fetch("/api/websites/categories").then(res => res.json()).then(data => {
            const c = []
            data.categories.forEach(item => {
                c.push({label: item, value: item});
            });
            setCategories(c);
        });
    }, []);

    function cancel() {
        setVisible(false);
    }

    return (
        <Dialog visible={true} header={website ? "更新网址" : "添加网址"} cancelBtn={null} confirmBtn={null} onEscKeydown={cancel} onCloseBtnClick={cancel} onOverlayClick={cancel}>
            <Form>
                <FormItem label="名称" name={"name"}>
                    <Input maxlength={64} />
                </FormItem>
                <FormItem label="网址" name={"url"}>
                    <Input maxlength={2048} />
                </FormItem>
                <FormItem label={"分类"} name={"category"}>
                    <Select options={categories} filterable creatable/>
                </FormItem>
                <FormItem label={"常用"} name={"topmost"}>
                    <Checkbox />
                </FormItem>
            </Form>
        </Dialog>
    )
}